_CHAIN_CONFIG = polite_download.PoliteDownloadConfig(
    user_agent="TestBot/1.0", retry=polite_download.RetryConfig(max_attempts=1)
)


def _session_on(transport):
    session = requests.Session()
    session.max_redirects = 3
    session.mount("https://", transport)
    return session


def _follow_with_requests(first_url, headers, answers):
    transport = _Transport(answers)
    session = _session_on(transport)
    session.headers.update(_CHAIN_CONFIG.give_base_headers())
    try:
        response = session.request(
            "GET",
            first_url,
            headers=headers or None,
            timeout=_CHAIN_CONFIG.default_timeout_s,
        )
        ending = (response.url, response.content)
    except requests.TooManyRedirects:
        ending = "too many redirects"
    return transport.sent, ending


def _follow_with_downloader(first_url, headers, answers):
    transport = _Transport(answers)
    downloader = polite_download.PoliteDownloader(
        _CHAIN_CONFIG, session=_session_on(transport)
    )
    try:
        result = downloader._request(
            "GET", first_url, headers=headers or None, allow_cache=False
        )
        ending = (result.final_url, result.body)
    except requests.TooManyRedirects:
        ending = "too many redirects"
    return transport.sent, ending


class PoliteDownloadTests(unittest.TestCase):
    def test_retries_transient_status_then_returns_text(self):
        session = _FakeSession(
            [
                _FakeResponse(status_code=503),
                _FakeResponse(body=b"shalom\n"),
            ]
        )
        sleep_calls = []
        config = polite_download.PoliteDownloadConfig(
            user_agent="TestBot/1.0",
            default_timeout_s=9.0,
            retry=polite_download.RetryConfig(max_attempts=2, first_backoff_s=1.25),
        )
        downloader = polite_download.PoliteDownloader(
            config,
            session=session,
            sleep_fun=sleep_calls.append,
        )

        text = downloader.get_text("https://example.test/data")

        self.assertEqual("shalom\n", text)
        self.assertEqual([1.25], sleep_calls)
        self.assertEqual(2, len(session.calls))
        self.assertEqual(9.0, session.calls[0]["timeout"])

    def test_cache_reuses_previous_body_after_304(self):
        with tempfile.TemporaryDirectory() as cache_dir:
            session = _FakeSession(
                [
                    _FakeResponse(
                        body=b"cached text",
                        headers={
                            "ETag": '"v1"',
                            "Last-Modified": "Mon, 14 Apr 2025 00:00:00 GMT",
                        },
                    ),
                    _FakeResponse(status_code=304),
                ]
            )
            config = polite_download.PoliteDownloadConfig(
                user_agent="TestBot/1.0",
                cache=polite_download.CacheConfig(dir_path=cache_dir),
                retry=polite_download.RetryConfig(max_attempts=1),
            )
            downloader = polite_download.PoliteDownloader(config, session=session)

            first_text = downloader.get_text("https://example.test/data")
            second_text = downloader.get_text("https://example.test/data")

        self.assertEqual("cached text", first_text)
        self.assertEqual("cached text", second_text)
        self.assertEqual('"v1"', session.calls[1]["headers"]["If-None-Match"])
        self.assertEqual(
            "Mon, 14 Apr 2025 00:00:00 GMT",
            session.calls[1]["headers"]["If-Modified-Since"],
        )

    def test_disallowed_robots_blocks_fetch(self):
        session = _FakeSession(
            [
                _FakeResponse(
                    body=b"User-agent: *\nDisallow: /blocked\n",
                    url="https://example.test/robots.txt",
                )
            ]
        )
        config = polite_download.PoliteDownloadConfig(
            user_agent="TestBot/1.0",
            obey_robots_txt=True,
            retry=polite_download.RetryConfig(max_attempts=1),
        )
        downloader = polite_download.PoliteDownloader(config, session=session)

        with self.assertRaises(polite_download.RobotsDisallowedError):
            downloader.get_text("https://example.test/blocked/page")

        self.assertEqual(1, len(session.calls))
        self.assertEqual("https://example.test/robots.txt", session.calls[0]["url"])

    def test_throttle_waits_between_same_host_requests(self):
        session = _FakeSession(
            [
                _FakeResponse(body=b"first"),
                _FakeResponse(body=b"second"),
            ]
        )
        sleep_calls = []
        # The third reading is the throttle's, after its sleep.
        monotonic_values = iter([0.0, 0.5, 2.5])
        config = polite_download.PoliteDownloadConfig(
            user_agent="TestBot/1.0",
            throttle=polite_download.ThrottleConfig(min_delay_s=1.5, mean_delay_s=3.0),
            retry=polite_download.RetryConfig(max_attempts=1),
        )
        downloader = polite_download.PoliteDownloader(
            config,
            session=session,
            sleep_fun=sleep_calls.append,
            monotonic_fun=lambda: next(monotonic_values),
            expovariate_fun=lambda _: 1.0,
        )

        downloader.get_text("https://example.test/data")
        downloader.get_text("https://example.test/data")

        self.assertEqual([2.0], sleep_calls)

    def test_redirects_are_followed_as_requests_follows_them(self):
        """Differential, with requests' own redirect following as the oracle.

        The downloader follows a redirect one hop at a time, so that its throttle and
        its robots check see each hop.  Each chain must send the same requests, with
        the same headers and settings, and end the same way.
        """
        for first_url, headers, answers in _REDIRECT_CHAINS:
            with self.subTest(first_url=first_url):
                self.assertEqual(
                    _follow_with_requests(first_url, headers, answers),
                    _follow_with_downloader(first_url, headers, answers),
                )


